import{_ as n,o as t,c as e,a2 as i}from"./chunks/framework.CCtxZRER.js";const o=JSON.parse('{"title":"K3 di Gudang","description":"Hal keselamatan dan kesehatan kerja yang perlu diperhatikan peserta magang di area gudang.","frontmatter":{"title":"K3 di Gudang","description":"Hal keselamatan dan kesehatan kerja yang perlu diperhatikan peserta magang di area gudang.","status":"draf","dasar":"praktik umum K3 pergudangan","catatan":false,"catatan_status":"Ini ringkasan umum untuk belajar, bukan pengganti peraturan K3 perusahaan. Aturan K3 resmi selalu berlaku dan tidak boleh dikurangi berdasarkan isi halaman ini.","nomor_dokumen":null,"versi":0.1,"pemilik":"Gudang Teknik","pengesah":null,"diperbarui":"2026-10-13T00:00:00.000Z","kategori":"SOP","sumber":["ppt-gudang-teknik"],"kata_kunci":["K3","keselamatan","APD","PPE","helm","safety shoes","sarung tangan","goggles","mengangkat beban","APAR","darurat","bahan mudah terbakar"]},"headers":[],"relativePath":"sop/k3-gudang.md","filePath":"sop/k3-gudang.md"}'),r={name:"sop/k3-gudang.md"};function d(l,a,u,s,k,g){return t(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="k3-di-gudang" tabindex="-1">K3 di Gudang <a class="header-anchor" href="#k3-di-gudang" aria-label="Permalink to &quot;K3 di Gudang&quot;">​</a></h1><div class="danger custom-block"><p class="custom-block-title">Aturan resmi selalu didahulukan</p><p>Halaman ini adalah ringkasan umum untuk belajar. Peraturan K3 perusahaan, rambu di area kerja, dan instruksi petugas K3 atau pembimbing <strong>selalu berlaku</strong> dan lebih tinggi dari isi handbook ini.</p></div><p>Materi Gudang Teknik menutup dengan empat kata: <strong>akurasi, kerapian, kecepatan, keselamatan</strong>. Keselamatan berarti tidak ada pekerjaan gudang yang cukup mendesak untuk dikerjakan dengan cara yang tidak aman.</p><h2 id="alat-pelindung-diri-apd" tabindex="-1">Alat pelindung diri (APD) <a class="header-anchor" href="#alat-pelindung-diri-apd" aria-label="Permalink to &quot;Alat pelindung diri (APD)&quot;">​</a></h2><p>Gudang Teknik menyimpan dan menyalurkan APD seperti sarung tangan, helm, safety shoes, dan goggles. APD yang <strong>wajib</strong> dipakai peserta magang di setiap area perlu dikonfirmasi ke pembimbing.</p><ul class="daftar-periksa"><li>Saya tahu APD apa yang wajib dipakai di area gudang.</li><li>APD saya dalam kondisi baik dan ukurannya pas.</li><li>Saya tahu ke mana harus meminta APD pengganti jika rusak.</li></ul><h2 id="risiko-umum-dan-cara-menghindarinya" tabindex="-1">Risiko umum dan cara menghindarinya <a class="header-anchor" href="#risiko-umum-dan-cara-menghindarinya" aria-label="Permalink to &quot;Risiko umum dan cara menghindarinya&quot;">​</a></h2><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Risiko</th><th>Contoh situasi</th><th>Cara menghindari</th></tr></thead><tbody><tr><td data-label="Risiko">Tertimpa barang</td><td data-label="Contoh situasi">Barang jatuh dari rak tinggi</td><td data-label="Cara menghindari">Jangan menumpuk berlebihan, pakai helm bila diwajibkan, letakkan barang berat di bawah</td></tr><tr><td data-label="Risiko">Cedera punggung</td><td data-label="Contoh situasi">Mengangkat barang berat sendirian</td><td data-label="Cara menghindari">Tekuk lutut, jaga punggung lurus, minta bantuan atau pakai alat angkut</td></tr><tr><td data-label="Risiko">Terluka benda tajam</td><td data-label="Contoh situasi">Membuka kemasan, memegang plat atau cutting disc</td><td data-label="Cara menghindari">Pakai sarung tangan, buka kemasan dengan alat yang sesuai</td></tr><tr><td data-label="Risiko">Terpeleset atau tersandung</td><td data-label="Contoh situasi">Ceceran oli, barang di jalur jalan</td><td data-label="Cara menghindari">Bersihkan ceceran sesuai prosedur, jaga jalur tetap bersih</td></tr><tr><td data-label="Risiko">Kebakaran</td><td data-label="Contoh situasi">Oli, grease, atau sealant dekat sumber panas</td><td data-label="Cara menghindari">Simpan di area yang ditentukan dan kemasan tertutup, ketahui lokasi APAR</td></tr><tr><td data-label="Risiko">Tertabrak alat angkut</td><td data-label="Contoh situasi">Forklift atau alat angkut lain melintas</td><td data-label="Cara menghindari">Berjalan di jalur pejalan kaki dan jangan berdiri di area manuver</td></tr><tr><td data-label="Risiko">Iritasi mata atau kulit</td><td data-label="Contoh situasi">Kontak dengan bahan kimia consumable</td><td data-label="Cara menghindari">Pakai sarung tangan dan goggles, baca label dan lembar data keselamatan (SDS)</td></tr></tbody></table><h2 id="aturan-dasar-untuk-peserta-magang" tabindex="-1">Aturan dasar untuk peserta magang <a class="header-anchor" href="#aturan-dasar-untuk-peserta-magang" aria-label="Permalink to &quot;Aturan dasar untuk peserta magang&quot;">​</a></h2><ol><li>Jangan mengoperasikan alat angkut bermesin, mesin, atau peralatan listrik tanpa izin dan pelatihan.</li><li>Jangan memanjat rak.</li><li>Jangan masuk ke area terbatas tanpa pendamping.</li><li>Laporkan kondisi tidak aman, seperti rak miring, kabel terkelupas, atau ceceran, kepada pembimbing.</li><li>Jika ragu apakah suatu pekerjaan aman, <strong>berhenti dan tanyakan</strong>.</li></ol><h2 id="jika-terjadi-keadaan-darurat" tabindex="-1">Jika terjadi keadaan darurat <a class="header-anchor" href="#jika-terjadi-keadaan-darurat" aria-label="Permalink to &quot;Jika terjadi keadaan darurat&quot;">​</a></h2><ol><li>Hentikan pekerjaan dan amankan diri.</li><li>Beri tahu orang di sekitar dan laporkan ke pembimbing atau petugas yang ditunjuk.</li><li>Ikuti jalur evakuasi menuju titik kumpul.</li><li>Jangan kembali ke area sampai dinyatakan aman.</li></ol><div class="info custom-block"><p class="custom-block-title">Perlu dilengkapi pembimbing</p><p>Nomor darurat internal, lokasi APAR dan kotak P3K, jalur evakuasi, serta titik kumpul belum tercantum. Lengkapi bagian ini bersama pembimbing atau petugas K3.</p></div>',13)])])}const p=n(r,[["render",d]]);export{o as __pageData,p as default};
